require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/schema.php';$schema=dental_schema($pdo);$labId=$schema->labId();$serviceCol=$schema->serviceId();$serviceName=$schema->serviceName();$imageId=$schema->imageId();$imagePath=$schema->imagePath();$published=$schema->status('valide');
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$lab=null;if($id){$q=$pdo->prepare("SELECT `$labId` id,nom_laboratoire,nom_gerant,telephone,email,adresse,ville,site_web,instagram,description"." FROM laboratoire WHERE `$labId`=? AND statut=? LIMIT 1");$q->execute([$id,$published]);$lab=$q->fetch();}if(!$lab)http_response_code(404);$images=[];$services=[];$similar=[];$phone='';$webUrl='';$mapsUrl='';
if($lab){$addressValue=trim((string)($lab['adresse']??''));$cityValue=trim((string)($lab['ville']??''));$addressIsMapUrl=filter_var($addressValue,FILTER_VALIDATE_URL)!==false;$mapsHost=strtolower((string)parse_url($addressValue,PHP_URL_HOST));$isGoogleMapsUrl=$addressIsMapUrl&&(in_array($mapsHost,['maps.app.goo.gl','goo.gl','maps.google.com'],true)||($mapsHost==='google.com'&&str_starts_with((string)parse_url($addressValue,PHP_URL_PATH),'/maps')));$mapsUrl=$isGoogleMapsUrl?$addressValue:(trim($addressValue.' '. $cityValue)!==''?'https://www.google.com/maps/search/?api=1&query='.rawurlencode(trim($addressValue.', '. $cityValue)):'');$addressText=$isGoogleMapsUrl?$cityValue:trim($addressValue.', '. $cityValue);$q=$pdo->prepare("SELECT `$imagePath` FROM image_laboratoire WHERE laboratoire_id=? ORDER BY `$imageId`");$q->execute([$id]);$images=$q->fetchAll(PDO::FETCH_COLUMN);$q=$pdo->prepare("SELECT s.`$serviceName` FROM service s JOIN laboratoire_service ls ON ls.service_id=s.`$serviceCol` WHERE ls.laboratoire_id=? ORDER BY s.`$serviceName`");$q->execute([$id]);$services=$q->fetchAll(PDO::FETCH_COLUMN);$q=$pdo->prepare("SELECT l.`$labId` id,l.nom_laboratoire,l.ville,(SELECT i.`$imagePath` FROM image_laboratoire i WHERE i.laboratoire_id=l.`$labId` ORDER BY i.`$imageId` LIMIT 1) photo FROM laboratoire l WHERE l.statut=? AND l.ville=? AND l.`$labId`<>? ORDER BY l.`$labId` DESC LIMIT 3");$q->execute([$published,$lab['ville'],$id]);$similar=$q->fetchAll();$phone=preg_replace('/[^0-9+]/','',(string)$lab['telephone']);foreach(['site_web','instagram'] as $field){$url=trim((string)($lab[$field]??''));if($url!==''&&filter_var($url,FILTER_VALIDATE_URL)&&in_array(strtolower((string)parse_url($url,PHP_URL_SCHEME)),['http','https'],true)&&$field==='site_web')$webUrl=$url;}}

$detailIcon=static function(string $name):string{$paths=['pin'=>'<path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>','phone'=>'<path d="M7 3h3l2 5-2 2a15 15 0 0 0 4 4l2-2 5 2v3a2 2 0 0 1-2 2A16 16 0 0 1 5 5a2 2 0 0 1 2-2Z"/>','mail'=>'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m4 7 8 6 8-6"/>','globe'=>'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a15 15 0 0 1 0 18M12 3a15 15 0 0 0 0 18"/>','map'=>'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3Z"/><path d="M9 3v15m6-12v15"/>','external'=>'<path d="M14 4h6v6m0-6-9 9"/><path d="M18 13v6a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1h6"/>','copy'=>'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>','arrow'=>'<path d="M4 12h15m-6-6 6 6-6 6"/>','shield'=>'<path d="M12 22s8-4 8-11V5l-8-3-8 3v6c0 7 8 11 8 11Z"/><path d="m9 12 2 2 4-4"/>','handshake'=>'<path d="m3 12 4-4 4 2 2-2 8 4-4 5-4-2-3 2-7-5Z"/><path d="m7 8 3-3 5 1 2 2M8 15l3 2m1-4 3 2m1-4 3 2"/>','headset'=>'<path d="M4 13v-2a8 8 0 0 1 16 0v2"/><rect x="3" y="12" width="4" height="7" rx="2"/><rect x="17" y="12" width="4" height="7" rx="2"/><path d="M17 19a5 3 0 0 1-5 3h-1"/>'];return '<svg class="detail-svg" viewBox="0 0 24 24" aria-hidden="true" focusable="false">'.($paths[$name]??'').'</svg>';};$emailAddress=$lab?trim((string)($lab['email']??'')):'';$emailAddress=filter_var($emailAddress,FILTER_VALIDATE_EMAIL)?$emailAddress:'';$gmailComposeUrl='';$mailtoFallback='';if($emailAddress!==''){$subject='Demande de renseignements et de collaboration – DentalLink Morocco';$body="Madame, Monsieur,\n\nJe me permets de vous contacter afin de me présenter et d’échanger avec votre laboratoire au sujet des services dentaires que vous proposez.\n\nJe souhaiterais obtenir des renseignements complémentaires et discuter d’une éventuelle collaboration.\n\nNom : [Votre nom]\nCoordonnées : [Votre téléphone et/ou e-mail]\nMessage personnel : [Votre message]\n\nJe vous remercie par avance pour votre réponse et vous prie d’agréer, Madame, Monsieur, mes salutations distinguées.\n\n[Votre nom]";$composeParams=['view'=>'cm','fs'=>'1','to'=>$emailAddress,'su'=>$subject,'body'=>$body];$gmailComposeUrl='https://mail.google.com/mail/?'.http_build_query($composeParams,'','&',PHP_QUERY_RFC3986);$mailtoFallback='mailto:'.$emailAddress.'?'.http_build_query(['subject'=>$subject,'body'=>$body],'','&',PHP_QUERY_RFC3986);}
$pageTitle=$lab?($lab['nom_laboratoire'].' — DentalLink Morocco'):'Laboratoire introuvable — DentalLink';$pageDescription=$lab?'Coordonnées, photos et services de '.$lab['nom_laboratoire'].' à '.$lab['ville'].'.':'Fiche introuvable dans l’annuaire.';$pageStyles=['assets/css/public.css'];$loadInterFont=true;require __DIR__.'/includes/header.php';require_once __DIR__.'/includes/public-nav.php';
?>
