<div class="detail-contact-row"><span class="detail-contact-icon" aria-hidden="true"><?=$detailIcon('mail')?></span><div class="detail-contact-copy"><span>E-mail</span><strong><?php if($emailAddress!==''):?><?=e($emailAddress)?><?php else:?>Non renseigné<?php endif;?></strong></div><?php if($emailAddress!==''):?><button class="detail-copy-button" type="button" data-copy="<?=e($emailAddress)?>" aria-label="Copier l’adresse e-mail"><?=$detailIcon('copy')?></button><?php endif;?></div>
